/* Theme Parks & Attractions set additions — cards appended after theme-parks.js.
   (theme-parks.js exceeds the push size limit, so remaining cards live here instead of being
   edited into it. Must stay directly after 'theme-parks.js' in sets/manifest.js.) */
(function () {
  var S = window.CardSets && window.CardSets.get('theme-parks');
  if (!S) return;
  var extra = [{"name":"Prince Charming Regal Carrousel","rarity":"common","id":"prince-charming-regal-carrousel","subtitle":"Dark Rides & Classic Attractions","details":"Ninety hand-painted white horses circle under scenes from Cinderella on this 1917 carousel, brought to Magic Kingdom from Maplewood, New Jersey in 1971.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cinderella%27s%20Horse%20on%20Carousel%20at%20Magic%20Kingdom%20Walt%20Disney%20World%20-%202451902987.jpg?width=1024"},{"name":"Pixar Pal-A-Round","rarity":"common","id":"pixar-pal-a-round","subtitle":"Dark Rides & Classic Attractions","details":"Swinging and fixed gondolas circle a giant Pixar Ferris wheel over Paradise Bay at California Adventure, with Mickey's face at its hub, in form since 2009.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Pixar%20Pal-A-Round%202019.jpg?width=1024"},{"name":"Golden Zephyr","rarity":"common","id":"golden-zephyr","subtitle":"Dark Rides & Classic Attractions","details":"Silver rocket ships swing outward over Paradise Bay in this aerial carousel at California Adventure, evoking the mulholland-style rides of old boardwalks since 2001.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Golden%20Zephyr.jpg?width=1024"},{"name":"Silly Symphony Swings","rarity":"common","id":"silly-symphony-swings","subtitle":"Dark Rides & Classic Attractions","details":"Chair swings spin riders around a band-concert tornado from the 1935 Mickey short The Band Concert at California Adventure, in current form since 2010.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Silly%20Symphony%20Swings.jpg?width=1024"},{"name":"Jumpin' Jellyfish","rarity":"common","id":"jumpin-jellyfish","subtitle":"Dark Rides & Classic Attractions","details":"Jellyfish gondolas rise and parachute gently down over Paradise Bay in this small drop ride at California Adventure, opened in 2001.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Jumpin%20Jellyfish.jpg?width=1024"},{"name":"Caro-Seuss-el","rarity":"common","id":"caro-seuss-el","subtitle":"Dark Rides & Classic Attractions","details":"Unusual Seuss creatures replace horses on this gentle carousel in Seuss Landing at Islands of Adventure, where riders can move their mounts' heads, opened in 1999.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Caro-Seuss-el.jpg?width=1024"},{"name":"Flying Machines","rarity":"common","id":"flying-machines","subtitle":"Dark Rides & Classic Attractions","details":"Sir Hiram Maxim's spinning flying machines at Blackpool Pleasure Beach have whirled riders in caged cars since 1904, among Britain's oldest surviving rides.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Hiram%20Maxim%20Captive%20Flying%20Machines.jpg?width=1024"},{"name":"Ghost Train","rarity":"common","id":"ghost-train","subtitle":"Dark Rides & Classic Attractions","details":"Blackpool Pleasure Beach's Ghost Train, opened in 1930, is credited as the first ride to use that now-universal name for a haunted dark ride.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Ghost%20train%20%28Pleasure%20Beach%20Blackpool%29.JPG?width=1024"},{"name":"River Caves","rarity":"common","id":"river-caves","subtitle":"Dark Rides & Classic Attractions","details":"Boats drift through caverns of world wonders, dinosaurs and a blue grotto in Blackpool Pleasure Beach's River Caves, a water dark ride dating to 1905.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/River%20Caves%2C%20Blackpool%20Pleasure%20Beach..jpg?width=1024"},{"name":"Derby Racer","rarity":"common","id":"derby-racer","subtitle":"Dark Rides & Classic Attractions","details":"Riders race galloping horses that actually move forward and back on Blackpool Pleasure Beach's Derby Racer, a rare surviving racing-horse carousel from 1959.","image":"https://images.coasterpedia.net/thumb/d/d0/Derby_Racer_%28Blackpool_Pleasure_Beach%29_2006_01.jpg/1024px-Derby_Racer_%28Blackpool_Pleasure_Beach%29_2006_01.jpg.webp"},{"name":"Cedar Downs Racing Derby","rarity":"common","id":"cedar-downs-racing-derby","subtitle":"Dark Rides & Classic Attractions","details":"Horses race side by side as the whole platform spins on this Cedar Point carousel, one of only two surviving racing derby carousels in America, dating to 1920.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cedar%20Downs%20Horses.jpg?width=1024"},{"name":"Cedar Point & Lake Erie Railroad","rarity":"common","id":"cedar-point-and-lake-erie-railroad","subtitle":"Dark Rides & Classic Attractions","details":"Steam trains carry riders through Boneville's skeleton scenes and along Lake Erie on this Cedar Point railroad, opened in 1963.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cedar%20Point%20%26%20Lake%20Erie%20Railroad%20Judy%20K.%20locomotive%20-%20August%202023.jpg?width=1024"},{"name":"Giant Wheel","rarity":"common","id":"giant-wheel","subtitle":"Dark Rides & Classic Attractions","details":"Cedar Point's 136-foot Ferris wheel lifts gondolas high over Lake Erie and the midway, a landmark of the park's skyline since it opened in 1972.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cedar%20Point%20Giant%20Wheel%20%285847052327%29.jpg?width=1024"},{"name":"Sky Ride (Cedar Point)","rarity":"common","id":"sky-ride-cedar-point","subtitle":"Dark Rides & Classic Attractions","details":"Gondolas glide on cables high above Cedar Point's main midway in this Von Roll sky ride, carrying riders between the front and middle of the park since 1961.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Cedar%20Point%20Sky%20Ride.jpg?width=1024"},{"name":"Efteling Steam Train","rarity":"common","id":"efteling-steam-train","subtitle":"Dark Rides & Classic Attractions","details":"Steam locomotives circle Efteling on a narrow-gauge line with a station in the fairy tale forest area, carrying park guests since 1969.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Efteling%20Stoomtrein.jpg?width=1024"},{"name":"Sirocco","rarity":"common","id":"sirocco","subtitle":"Dark Rides & Classic Attractions","details":"Efteling's spinning teacup-style ride whirls merchant boats in a storm off Sinbad the Sailor's harbour, rethemed in 2022 from the long-running Monsieur Cannibale.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Efteling%20Sirocco.jpg?width=1024"},{"name":"Volk van Laaf Monorail","rarity":"common","id":"volk-van-laaf-monorail","subtitle":"Dark Rides & Classic Attractions","details":"Small snail-like monorail cars glide at walking pace through the village of the Laaf people in Efteling, a gentle elevated tour opened in 1990.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Volk%20van%20Laaf%20monorail%201.JPG?width=1024"},{"name":"Tiroler Wildwasserbahn","rarity":"common","id":"tiroler-wildwasserbahn","subtitle":"Dark Rides & Classic Attractions","details":"Log boats float through an Alpine village and splash down a waterfall in Europa-Park's Austrian area, a classic Mack log flume opened in 1978.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Europa-Park%20-%20Tiroler%20Wildwasserbahn%20%2803%29.JPG?width=1024"},{"name":"Reese's Cupfusion","rarity":"common","id":"reeses-cupfusion","subtitle":"Dark Rides & Classic Attractions","details":"Interactive cars zap targets to guard Reese's crystals in Hersheypark's gaming dark ride, opened in 2019 on the site of the park's classic Reese's Xtreme Cup Challenge.","image":"https://cdn.prod.website-files.com/596e3d14635c203ba1480ad5/5f319e650eb31ba6004b1bb5_RCF_blog.jpg"},{"name":"Grand Carousel","rarity":"common","id":"grand-carousel","subtitle":"Dark Rides & Classic Attractions","details":"Knoebels' 1913 Grand Carousel lets riders grab for brass rings thrown from a mechanical arm, one of the last ring-catching carousels in America.","image":"https://commons.wikimedia.org/wiki/Special:FilePath/Knoebels%20Grand%20Carousel.jpg?width=1024"},{"name":"Horizons","rarity":"legendary","id":"horizons","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1983-1999 at EPCOT. This pavilion ride carried guests through visions of 21st-century living, from desert farms to undersea and space colonies.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/82/Horizons_%28Epcot%29_1.jpg/1280px-Horizons_%28Epcot%29_1.jpg?utm_source=en.wikipedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"The Great Movie Ride","rarity":"legendary","id":"the-great-movie-ride","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1989-2017 at Disney's Hollywood Studios. Riders toured recreated scenes from classic films, ending with a montage of cinema history.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/The_Great_Movie_Ride_-_Disney%27s_Hollywood_Studios_%285480336421%29.jpg/1280px-The_Great_Movie_Ride_-_Disney%27s_Hollywood_Studios_%285480336421%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Jaws (Universal Studios Florida)","rarity":"legendary","id":"jaws-universal-studios-florida","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1990-2012 at Universal Studios Florida. A boat tour past a massive shark turned into a chase when the animatronic great white attacked.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f7/UniversalStudiosJawsShark.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"20,000 Leagues Under the Sea (Magic Kingdom)","rarity":"legendary","id":"20000-leagues-under-the-sea-magic-kingdom","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1971-1994 at Magic Kingdom. Guests boarded Captain Nemo's Nautilus submarines for a voyage past sea creatures, mermaids and a giant squid.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6a/Disney_world_submarine_ride_1998.jpg/1280px-Disney_world_submarine_ride_1998.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Back to the Future: The Ride","rarity":"epic","id":"back-to-the-future-the-ride","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1991-2007 at Universal Studios Florida. The simulator sent riders in DeLoreans chasing Biff through Hill Valley, ice caves and dinosaur times.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f2/Back_to_the_Future_DeLorean_-_Universal_Studios_Florida.jpg/1280px-Back_to_the_Future_DeLorean_-_Universal_Studios_Florida.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Maelstrom","rarity":"epic","id":"maelstrom","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1988-2014 at EPCOT's Norway pavilion. A boat ride past trolls and polar bears sent guests backwards before a plunge toward a North Sea storm.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/Maelstrom_entrance_sign.jpg/1280px-Maelstrom_entrance_sign.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Splash Mountain","rarity":"epic","id":"splash-mountain","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1989-2023 in the US Disney parks. This log flume followed Br'er Rabbit past singing critters to a five-story drop into the briar patch.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/Splash_Mountain_at_Disneyland.JPG/1280px-Splash_Mountain_at_Disneyland.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Mr. Toad's Wild Ride (Magic Kingdom)","rarity":"epic","id":"mr-toads-wild-ride-magic-kingdom","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1971-1998 at Magic Kingdom. Toad's reckless motorcar ride crashed through London scenes and ended, famously, in a fiery underworld.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b3/Toadhall.jpg?utm_source=en.wikipedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Action Park","rarity":"epic","id":"action-park","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1978-1996 in Vernon, New Jersey. Nicknamed 'Class Action Park', it became infamous for its looping water slide, alpine slide and rough edges.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fd/Action_Park_%282999332709%29.jpg/1280px-Action_Park_%282999332709%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Geauga Lake","rarity":"epic","id":"geauga-lake","subtitle":"Defunct Parks & Lost Rides","details":"Operated as an amusement park 1887-2007 in Ohio. The lakeside park grew from picnics and a carousel into a major park beside Lake Erie.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/Villain_Geauga_Lake.JPG/1280px-Villain_Geauga_Lake.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Kongfrontation","rarity":"rare","id":"kongfrontation","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1990-2002 at Universal Studios Florida. A tram tour through New York ended face to face with a towering King Kong animatronic.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dd/Kongfrontation_1.jpg/1280px-Kongfrontation_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"ExtraTERRORestrial Alien Encounter","rarity":"rare","id":"extraterrorestrial-alien-encounter","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1995-2003 at Magic Kingdom. This intense Tomorrowland theatre show used sound, air and restraints to make an alien seem loose in the room.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/ExtraTERRORestrial_Alien_Encounter_1.jpg/1280px-ExtraTERRORestrial_Alien_Encounter_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Snow White's Scary Adventures","rarity":"rare","id":"snow-whites-scary-adventures","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1971-2012 at Magic Kingdom. The dark ride retold Snow White's story through the Evil Queen, the witch and the dwarfs' mine.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9f/Snow_White%27s_Scary_Adventures_Entrance.jpg/1280px-Snow_White%27s_Scary_Adventures_Entrance.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"World of Motion","rarity":"rare","id":"world-of-motion","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1982-1996 at EPCOT. Hosted by General Motors, the omnimover traced transport history from the wheel to traffic jams of the future.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c8/World_of_Motion_1.jpg/1280px-World_of_Motion_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Journey Into Imagination (1983)","rarity":"rare","id":"journey-into-imagination-1983","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1983-1998 at EPCOT. Dreamfinder and Figment led the original ride, a colorful tour of imagination built around the song 'One Little Spark'.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/11/EpcotImagination.JPG/1280px-EpcotImagination.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Studio Backlot Tour","rarity":"rare","id":"studio-backlot-tour","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1989-2014 at Disney's Hollywood Studios. The tram tour visited costume and prop shops, then survived the flash flood of Catastrophe Canyon.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/97/Catastrophe_Canyon.jpg/1280px-Catastrophe_Canyon.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Riverview Park (Chicago)","rarity":"rare","id":"riverview-park-chicago","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1904-1967 in Chicago. For six decades it packed in rides, games and midway attractions as a classic American amusement park.","image":"https://upload.wikimedia.org/wikipedia/commons/b/bc/Entrance_to_Riverview_Park_%28JJH%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Opryland USA","rarity":"rare","id":"opryland-usa","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1972-1997 in Nashville, Tennessee. The music-themed park mixed rides with live country, gospel and Americana shows by the Cumberland River.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9a/Skyride_Opryland_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Six Flags New Orleans","rarity":"rare","id":"six-flags-new-orleans","subtitle":"Defunct Parks & Lost Rides","details":"Operated 2000-2005 in Louisiana, first as Jazzland. Flooded by Hurricane Katrina, the park never reopened and its rides stood abandoned for years.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/Aerial_view_of_SFNO_after_Hurricane_Katrina_edit.jpg/1280px-Aerial_view_of_SFNO_after_Hurricane_Katrina_edit.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Body Wars","rarity":"rare","id":"body-wars","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1989-2007 at EPCOT's Wonders of Life pavilion. The simulator shrank riders into the human bloodstream on a medical rescue mission.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/Body_Wars_%28358808748%29.jpg/1280px-Body_Wars_%28358808748%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Cranium Command","rarity":"uncommon","id":"cranium-command","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1989-2007 at EPCOT's Wonders of Life pavilion. A young recruit piloted a teenager's brain, with organs arguing in the control room.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/Cranium_Command_%28358808645%29.jpg/1280px-Cranium_Command_%28358808645%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Ellen's Energy Adventure","rarity":"uncommon","id":"ellens-energy-adventure","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1996-2017 at EPCOT. Ellen DeGeneres dreamed of a Jeopardy! game, then rode past dinosaurs in a vast primeval diorama about energy.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b0/Universe_of_Energy_%2823052612180%29.jpg/1280px-Universe_of_Energy_%2823052612180%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"The Timekeeper","rarity":"uncommon","id":"the-timekeeper","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1994-2006 at Magic Kingdom. The Circle-Vision film let a robot host send guests through history and into a vision of future Paris.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c2/Timekeeper.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Skyway (Magic Kingdom)","rarity":"uncommon","id":"skyway-magic-kingdom","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1971-1999 at Magic Kingdom. Gondola buckets carried guests between Fantasyland and Tomorrowland with a bird's-eye view over the park.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6d/Defunct_Skyway_station_at_Magic_Kingdom.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Delta Dreamflight","rarity":"uncommon","id":"delta-dreamflight","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1989-1998 at Magic Kingdom. Sponsored by Delta Air Lines, the ride traced flight history from balloons and barnstormers to jets.","image":"https://vignette.wikia.nocookie.net/disney/images/6/61/Dreamflight_Spirit_of_Delta.jpg/revision/latest/scale-to-width-down/1024?cb=20200201183450"},{"name":"If You Had Wings","rarity":"uncommon","id":"if-you-had-wings","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1972-1989 at Magic Kingdom. This omnimover ride, sponsored by Eastern Air Lines, flew guests to Caribbean and Mexican scenes.","image":"https://vignette.wikia.nocookie.net/disney/images/0/07/If_You_Had_Wings_Load.jpg/revision/latest?cb=20180419204058"},{"name":"Kitchen Kabaret","rarity":"uncommon","id":"kitchen-kabaret","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1982-1994 at EPCOT's Land pavilion. Singing food characters, led by Bonnie Appetite, performed a musical revue about healthy eating.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b9/Kitchen_Krackpots.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Mike Fink Keel Boats","rarity":"uncommon","id":"mike-fink-keel-boats","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1971-1997 at Magic Kingdom. Flat-bottomed keel boats based on the Davy Crockett films cruised the Rivers of America.","image":"https://upload.wikimedia.org/wikipedia/commons/6/64/Mike_Fink_Keel_Boat_on_the_River_of_the_Americas_in_Disneyland-1985-2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Davy Crockett Explorer Canoes (Magic Kingdom)","rarity":"uncommon","id":"davy-crockett-explorer-canoes-magic-kingdom","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1971-1994 at Magic Kingdom. Guests paddled big canoes around Tom Sawyer Island, guided by cast members in frontier dress.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Davy_Crockett_Explorer_Canoes.JPG/1280px-Davy_Crockett_Explorer_Canoes.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Six Flags Astroworld","rarity":"uncommon","id":"six-flags-astroworld","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1968-2005 in Houston, Texas. Judge Roy Hofheinz built the park across from the Astrodome; it became a Six Flags park in 1975.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/Greezed_Lightnin%27_%28Six_Flags_Astroworld%29_1.jpg/1280px-Greezed_Lightnin%27_%28Six_Flags_Astroworld%29_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Palisades Amusement Park","rarity":"uncommon","id":"palisades-amusement-park","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1898-1971 in New Jersey, across the Hudson from New York. Its salt water pool, midway and concerts made it a famed summer escape.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e9/Merry_go_round%2C_Palisades_Amusement_Park%2C_N._J._%288509246715%29.jpg/1280px-Merry_go_round%2C_Palisades_Amusement_Park%2C_N._J._%288509246715%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Euclid Beach Park","rarity":"uncommon","id":"euclid-beach-park","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1895-1969 on Cleveland's Lake Erie shore. The trolley park was known for its dance pavilions, bathing beach and classic rides.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2b/Flying_Scooter_-_Euclid_Beach_Park%2C_Cleveland%2C_Ohio_-_DPLA_-_ee55ecc9ca0b3a5e9cf9a1cc4226fbb7_%28page_1%29.jpg/1280px-Flying_Scooter_-_Euclid_Beach_Park%2C_Cleveland%2C_Ohio_-_DPLA_-_ee55ecc9ca0b3a5e9cf9a1cc4226fbb7_%28page_1%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Adventure Thru Inner Space","rarity":"uncommon","id":"adventure-thru-inner-space","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1967-1985 at Disneyland. Guests were 'shrunk' inside a snowflake aboard Monsanto's omnimover, watched by a giant microscope eye.","image":"https://vignette.wikia.nocookie.net/disney/images/6/69/Adventurethruinnerspace.jpg/revision/latest?cb=20131203175546"},{"name":"PeopleMover (Disneyland)","rarity":"uncommon","id":"peoplemover-disneyland","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1967-1995 at Disneyland. The slow elevated tram toured Tomorrowland on a system once pitched as future city transport.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a0/Monorail%2C_PeopleMover_and_Submarines%2C_Disneyland.jpg/1280px-Monorail%2C_PeopleMover_and_Submarines%2C_Disneyland.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Disaster!","rarity":"uncommon","id":"disaster","subtitle":"Defunct Parks & Lost Rides","details":"Operated 2008-2015 at Universal Studios Florida. Riders became extras in a disaster film, ending in a subway earthquake sequence.","image":"https://vignette.wikia.nocookie.net/universal-orlando/images/3/34/Universal_Studios_Disaster%21_A_Major_Motion_Picture_Ride...Starring_You%21.jpg/revision/latest/scale-to-width-down/1024?cb=20200427213419"},{"name":"Twister... Ride It Out","rarity":"uncommon","id":"twister-ride-it-out","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1998-2015 at Universal Studios Florida. Guests stood through a recreated tornado that tore apart a small-town drive-in scene.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/Twister_Ride_it_Out_01.jpg/1280px-Twister_Ride_it_Out_01.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Jimmy Neutron's Nicktoon Blast","rarity":"uncommon","id":"jimmy-neutrons-nicktoon-blast","subtitle":"Defunct Parks & Lost Rides","details":"Operated 2003-2011 at Universal Studios Florida. The simulator chase teamed Jimmy Neutron with other Nicktoons to stop an alien plot.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/db/JimmyNeutronEntrance.JPG/1280px-JimmyNeutronEntrance.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Terminator 2: 3-D","rarity":"uncommon","id":"terminator-2-3d","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1996-2017 at Universal Studios Florida. Live actors joined a 3-D film as the Terminator battled machines across time.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/69/Terminator_2_-_3D_Entrance_Universal_Studios_Florida.jpg/1280px-Terminator_2_-_3D_Entrance_Universal_Studios_Florida.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Submarine Voyage (Disneyland)","rarity":"uncommon","id":"submarine-voyage-disneyland","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1959-1998 at Disneyland. Its submarines passed reefs, a graveyard of lost ships, Atlantis ruins and a cartoonish sea serpent.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/Submarine_Lagoon_-_Disneyland_1978.jpg/1280px-Submarine_Lagoon_-_Disneyland_1978.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Rocket Rods","rarity":"uncommon","id":"rocket-rods","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1998-2000 at Disneyland. Fast vehicles raced around the old PeopleMover track, but breakdowns kept the ride closed more than open.","image":"https://upload.wikimedia.org/wikipedia/commons/6/69/Rocket_Rods%2C_Disneyland%2C_California.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Food Rocks","rarity":"common","id":"food-rocks","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1994-2004 at EPCOT's Land pavilion. Food characters parodied rock stars in a concert about nutrition, hosted by Fud Wrapper.","image":"https://vignette.wikia.nocookie.net/disney/images/3/34/Food_Rocks.jpg/revision/latest?cb=20110410191822"},{"name":"El Rio del Tiempo","rarity":"common","id":"el-rio-del-tiempo","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1982-2007 at EPCOT's Mexico pavilion. A gentle boat ride passed Aztec scenes, festivals and markets to a fireworks finale.","image":"https://vignette.wikia.nocookie.net/disney/images/7/74/Elrioentrance.jpg/revision/latest?cb=20150602003831"},{"name":"Mickey Mouse Revue","rarity":"common","id":"mickey-mouse-revue","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1971-1980 at Magic Kingdom, then in Tokyo until 2009. Mickey conducted an animatronic orchestra of Disney characters.","image":"https://upload.wikimedia.org/wikipedia/commons/6/63/Three_Caballeros_Return.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Flying Saucers","rarity":"common","id":"flying-saucers","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1961-1966 at Disneyland. Riders steered personal saucers hovering on air cushions, bumping each other around a Tomorrowland arena.","image":"https://lh3.googleusercontent.com/blogger_img_proxy/AEn0k_tT6nrvsAWsDN_-hUDNIjJLCgqYd3egQINt6KHRgZ36cqPMkzrMeZD28KCTe5pXg-uxbuHVxMOE0XLFj7ZHg9zDPOUkpQZT_Ag8aCqnI4jKOFH_wASuFd7fNpS4CGVuHVgEO5Z8HP3itKBBJ2MHpB3q_9lgrQzNCw=s0-d"},{"name":"Mine Train Through Nature's Wonderland","rarity":"common","id":"mine-train-through-natures-wonderland","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1960-1977 at Disneyland. A small train toured the Living Desert and Beaver Valley, past animatronic animals and Rainbow Caverns.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/57/Mine_Train_Accessory_at_Disneyland.jpg/1280px-Mine_Train_Accessory_at_Disneyland.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"The Funtastic World of Hanna-Barbera","rarity":"common","id":"the-funtastic-world-of-hanna-barbera","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1990-2002 at Universal Studios Florida. A simulator sent guests with Yogi Bear chasing Dick Dastardly, who had kidnapped Elroy Jetson.","image":"https://upload.wikimedia.org/wikipedia/en/9/95/The_Funtastic_World_of_Hanna-Barbera_at_Universal_Orlando_Resort.jpg?utm_source=en.wikipedia.org&utm_campaign=api&utm_content=thumbnail_unscaled"},{"name":"Nickelodeon Studios","rarity":"common","id":"nickelodeon-studios","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1990-2005 at Universal Studios Florida. Guests toured working soundstages where Nickelodeon filmed shows, ending in a game lab.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5e/Nickelodeon_Studios_in_Hard_Rock_Cafe.jpg/1280px-Nickelodeon_Studios_in_Hard_Rock_Cafe.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Honey, I Shrunk the Audience","rarity":"common","id":"honey-i-shrunk-the-audience","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1994-2010 at EPCOT. The 3-D show shrank the theatre audience during Professor Szalinski's inventor award ceremony.","image":"https://upload.wikimedia.org/wikipedia/commons/9/91/Honey%2C_I_Shrunk_The_Audience_%28Epcot%29_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Shrek 4-D (Universal Studios Florida)","rarity":"common","id":"shrek-4d-universal-studios-florida","subtitle":"Defunct Parks & Lost Rides","details":"Operated 2003-2022 at Universal Studios Florida. The 4-D film bridged the first two Shrek films, with moving seats and in-theatre effects.","image":"https://vignette.wikia.nocookie.net/universal-orlando/images/1/16/Shrek_4-D.JPG/revision/latest/scale-to-width-down/1024?cb=20180906183819"},{"name":"Alfred Hitchcock: The Art of Making Movies","rarity":"common","id":"alfred-hitchcock-the-art-of-making-movies","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1990-2003 at Universal Studios Florida. Guests helped recreate scenes from Psycho and other Hitchcock films, then saw how they were made.","image":"https://vignette.wikia.nocookie.net/universal-orlando/images/b/bc/Universal_Studios_Alfred_Hitchcock_The_Art_of_Making_Movies.jpg/revision/latest?cb=20200426222013"},{"name":"The Ghostbusters Spooktacular","rarity":"common","id":"the-ghostbusters-spooktacular","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1990-1996 at Universal Studios Florida. This stage show recreated the Ghostbusters' temple battle, with Slimer and Gozer effects.","image":"https://vignette.wikia.nocookie.net/universal-orlando/images/0/09/Universal_Studios_Ghostbusters_Spooktacular.jpg/revision/latest?cb=20200426225521"},{"name":"Who Wants to Be a Millionaire - Play It!","rarity":"common","id":"who-wants-to-be-a-millionaire-play-it","subtitle":"Defunct Parks & Lost Rides","details":"Operated 2001-2006 at Disney's Hollywood Studios. Guests played the TV quiz in a replica studio with fastest-finger contestant seats.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/Who_Wants_to_Be_a_Millionaire_%E2%80%93_Play_It%21_%28Disney%27s_Hollywood_Studios%29_1.jpg/1280px-Who_Wants_to_Be_a_Millionaire_%E2%80%93_Play_It%21_%28Disney%27s_Hollywood_Studios%29_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"TriceraTop Spin","rarity":"common","id":"triceratop-spin","subtitle":"Defunct Parks & Lost Rides","details":"Operated 2001-2025 at Disney's Animal Kingdom. This spinner lifted riders in triceratops vehicles over Chester and Hester's Dino-Rama.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/51/TriceraTop_Spin_-_Disney%27s_Animal_Kingdom.jpg/1280px-TriceraTop_Spin_-_Disney%27s_Animal_Kingdom.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Idora Park","rarity":"common","id":"idora-park","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1899-1984 in Youngstown, Ohio. The trolley park's ballroom and rides drew generations before a fire hastened its closure.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/47/Entrance_to_Idora_Park%2C_Youngstown%2C_Ohio._-_DPLA_-_2dd118b8889560c79fd19b378abda207_%28page_1%29.jpg/1280px-Entrance_to_Idora_Park%2C_Youngstown%2C_Ohio._-_DPLA_-_2dd118b8889560c79fd19b378abda207_%28page_1%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Coney Island (Cincinnati)","rarity":"common","id":"coney-island-cincinnati","subtitle":"Defunct Parks & Lost Rides","details":"Operated as a ride park 1886-2023 in Cincinnati, Ohio. The Ohio River park was famed for its huge Sunlite Pool and a classic lakeside ride area.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/11/Sunlite_Pool%2C_Coney_Island%2C_Cincinnati%2C_Ohio_-_DPLA_-_ffb2ef19d5a725a10fcb5a4ff266d2eb_%28page_1%29.jpg/1280px-Sunlite_Pool%2C_Coney_Island%2C_Cincinnati%2C_Ohio_-_DPLA_-_ffb2ef19d5a725a10fcb5a4ff266d2eb_%28page_1%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Nara Dreamland","rarity":"common","id":"nara-dreamland","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1961-2006 in Nara, Japan. Built in Disneyland's image with its own castle and main street, it stood abandoned for a decade after closing.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/07/Nara_Dreamland%2C_Nara.jpg/1280px-Nara_Dreamland%2C_Nara.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Spreepark","rarity":"common","id":"spreepark","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1969-2001 in Berlin, Germany. East Germany's main amusement park survived reunification briefly, then decayed as an urban ruin.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Berlin_Spreepark_UAV_04-2017_img2.jpg/1280px-Berlin_Spreepark_UAV_04-2017_img2.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Pripyat Amusement Park","rarity":"common","id":"pripyat-amusement-park","subtitle":"Defunct Parks & Lost Rides","details":"Built for a May 1986 opening in Pripyat, Ukraine, it never officially opened; the Chernobyl disaster emptied the city days before its debut.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Pripyat_-_amusement_park_12.jpg/1280px-Pripyat_-_amusement_park_12.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Joyland Amusement Park (Wichita)","rarity":"common","id":"joyland-amusement-park-wichita","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1949-2004 in Wichita, Kansas. Louie the Clown, perched at the park's Wurlitzer organ, became its best-remembered mascot.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/47/Joyland_Wichita_Sign_2003.jpg/1280px-Joyland_Wichita_Sign_2003.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Bell's Amusement Park","rarity":"common","id":"bells-amusement-park","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1951-2006 in Tulsa, Oklahoma. The family-run park on the Tulsa fairgrounds mixed classic rides with midway games for over five decades.","image":"https://live.staticflickr.com/65535/53723503364_0ff156c713_b.jpg"},{"name":"Dogpatch USA","rarity":"common","id":"dogpatch-usa","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1968-1993 in Arkansas. Based on the Li'l Abner comic strip, the hillbilly-themed park sat in a hollow near Marble Falls.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/78/Dogpatch_USA_002.jpg/1280px-Dogpatch_USA_002.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Gulliver's Kingdom","rarity":"common","id":"gullivers-kingdom","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1997-2001 near Mount Fuji, Japan. A giant Gulliver figure lay tied down as the centerpiece of this short-lived Lilliput park.","image":"https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEhkFqC07e6mMomDlK8YalGI1BHXyc7p10kQZKT9Daf02MuHp0SbbXncOpgXWjKirabIR-_xAyiWOj7bNKTkKNJuvs8irOn6f3h1FOnJGTwp_8E1StxeP37yKBy8dPYljKfKhn8q9nsizA/s1600-rw/This+Abandoned+Japanese+Theme+Park+Is+The+Strangest+Place+You%E2%80%99ll+See+Today.jpg"},{"name":"Mimaland","rarity":"common","id":"mimaland","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1975-1994 in Gombak, Malaysia. One of Southeast Asia's early theme parks, it mixed a dinosaur area, a lake and water attractions.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/10/Gate_of_Mimaland.jpg/1280px-Gate_of_Mimaland.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Cascade Park","rarity":"common","id":"cascade-park","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1897-1985 in New Castle, Pennsylvania. The trolley park's dance pavilion hosted big bands, and its gorge setting framed the rides.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/Dance_Pavilion.jpg/1280px-Dance_Pavilion.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Bertrand Island","rarity":"common","id":"bertrand-island","subtitle":"Defunct Parks & Lost Rides","details":"Closed in 1983 on Lake Hopatcong, New Jersey. This lakeside park offered a carousel, midway games and dances in its ballroom pavilion.","image":"https://morristowngreen.com/wp-content/uploads/2020/07/Boardwalk-at-Bertrand-Island-Park-circa-1920-Lake-Hopatcong-NJ.jpg"},{"name":"Mountain Park (Holyoke)","rarity":"common","id":"mountain-park-holyoke","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1894-1987 in Holyoke, Massachusetts. The trolley park on Mount Tom combined picnic groves with rides and a popular dance hall.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/Mountain_Park%2C_Midway%2C_with_Mountain_Wildcat_Roller_Coaster%2C_c._1935_%28Holyoke%2C_Massachusetts%29.jpg/1280px-Mountain_Park%2C_Midway%2C_with_Mountain_Wildcat_Roller_Coaster%2C_c._1935_%28Holyoke%2C_Massachusetts%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Whalom Park","rarity":"common","id":"whalom-park","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1893-2000 in Lunenburg, Massachusetts. The trolley park beside Whalom Lake drew summer crowds for more than a century.","image":"https://upload.wikimedia.org/wikipedia/commons/b/bc/Whalom_comet_enter.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Kiddieland Amusement Park","rarity":"common","id":"kiddieland-amusement-park","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1929-2009 in Melrose Park, Illinois. Arthur Fritz founded the park with pony rides and miniature attractions for young children.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e8/Kiddieland_Amusement_Park_sign.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Libertyland","rarity":"common","id":"libertyland","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1976-2005 in Memphis, Tennessee. The fairgrounds park grew out of an earlier midway and hosted the city's annual Mid-South Fair.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d0/Libertyland_entrance.JPG/1280px-Libertyland_entrance.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Chippewa Lake Park","rarity":"common","id":"chippewa-lake-park","subtitle":"Defunct Parks & Lost Rides","details":"Operated 1878-1978 in Ohio. The lakeside resort park added rides, a ballroom and bathing beaches across a century of summers.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/Chippewa_Lake_Park_Tumble_Bug_%28November_2010%29_%282%29.jpg/1280px-Chippewa_Lake_Park_Tumble_Bug_%28November_2010%29_%282%29.jpg?utm_source=en.wikipedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Cinderella Castle","rarity":"legendary","id":"cinderella-castle","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Standing 189 feet over Magic Kingdom, this fairy-tale centerpiece opened in 1971, with a royal suite hidden inside its turreted towers.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/84/Cinderella_Castle.jpg/1280px-Cinderella_Castle.jpg"},{"name":"Spaceship Earth","rarity":"legendary","id":"spaceship-earth","subtitle":"Park Icons, Lands & Nighttime Shows","details":"EPCOT's 180-foot geodesic sphere houses a ride through communication history and has anchored the park's entrance plaza since 1982.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/Spaceship_Earth_2.jpg/1280px-Spaceship_Earth_2.jpg"},{"name":"Star Wars: Galaxy's Edge","rarity":"legendary","id":"star-wars-galaxys-edge","subtitle":"Park Icons, Lands & Nighttime Shows","details":"A 14-acre Star Wars outpost on the planet Batuu, built around the smuggler town of Black Spire Outpost and a full-size Millennium Falcon.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/Galaxy%27s_Edge_%2848390062657%29.jpg/960px-Galaxy%27s_Edge_%2848390062657%29.jpg"},{"name":"Fantasmic!","rarity":"legendary","id":"fantasmic","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Mickey's imagination becomes a riverfront battle of water screens, fireworks and villains in this nighttime spectacular first staged in 1992.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4e/Fantasmic%21_Evil_Queen_spell.jpg/1280px-Fantasmic%21_Evil_Queen_spell.jpg"},{"name":"Sleeping Beauty Castle (Disneyland)","rarity":"epic","id":"sleeping-beauty-castle-disneyland","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Disneyland's original 77-foot castle opened in 1955 and hides a walkthrough retelling of Sleeping Beauty in dioramas behind its drawbridge.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/Sleeping_Beauty_Castle_Disneyland_Anaheim_2013.jpg/1280px-Sleeping_Beauty_Castle_Disneyland_Anaheim_2013.jpg"},{"name":"Hogwarts Castle","rarity":"epic","id":"hogwarts-castle","subtitle":"Park Icons, Lands & Nighttime Shows","details":"This towering rock-and-turret Hogwarts replica crowns Hogsmeade at Islands of Adventure, its spires visible across the park's lagoon.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1f/Universal-Islands-of-Adventure-Harry-Potter-Castle-9127i.jpg/1280px-Universal-Islands-of-Adventure-Harry-Potter-Castle-9127i.jpg"},{"name":"Tree of Life","rarity":"epic","id":"tree-of-life","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Animal Kingdom's 145-foot icon carries more than 300 animals carved into its trunk, roots and branches, shading paths since the park opened in 1998.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Tree_of_Life%2C_Disney%27s_Animal_Kingdom.jpg/1280px-Tree_of_Life%2C_Disney%27s_Animal_Kingdom.jpg"},{"name":"Pandora — The World of Avatar","rarity":"epic","id":"pandora-the-world-of-avatar","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Avatar's alien valley at Animal Kingdom glows after dark with bioluminescent plants beneath mountains that appear to float overhead.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/Floating_Mountain_and_Goblin_Thistle_in_the_Valley_of_Mo%27ara_%2833546059874%29.jpg/1280px-Floating_Mountain_and_Goblin_Thistle_in_the_Valley_of_Mo%27ara_%2833546059874%29.jpg"},{"name":"Happily Ever After","rarity":"epic","id":"happily-ever-after","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Magic Kingdom's fireworks finale wraps Cinderella Castle in animated projections before Tinker Bell flies from its tallest spire.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/df/Fireworks_in_Magic_Kingdom.jpg/1280px-Fireworks_in_Magic_Kingdom.jpg"},{"name":"Main Street U.S.A.","rarity":"rare","id":"main-street-usa","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Turn-of-the-century storefronts inspired by Walt Disney's hometown of Marceline, Missouri, line the walk from the station to the castle.","image":"https://upload.wikimedia.org/wikipedia/commons/8/86/Magic_Kingdom_-_Main_Street_and_Trolley.jpg"},{"name":"World of Color","rarity":"rare","id":"world-of-color","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Nearly 1,200 fountains shoot water across Paradise Bay as film scenes play on mist screens in this California Adventure nighttime show.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/Disney%27s_California_Adventure_World_of_Color_IMG_4150.jpg/1280px-Disney%27s_California_Adventure_World_of_Color_IMG_4150.jpg"},{"name":"The Wizarding World of Harry Potter — Diagon Alley","rarity":"rare","id":"wizarding-world-diagon-alley","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Hidden behind a London brick wall at Universal Studios Florida, this wizarding street is watched by a fire-breathing dragon atop Gringotts Bank.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/85/Diagon_Alley_Universal_Studios.jpg/1280px-Diagon_Alley_Universal_Studios.jpg"},{"name":"Mount Prometheus","rarity":"rare","id":"mount-prometheus","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Tokyo DisneySea's erupting volcano dominates its harbor and hides caverns within, serving as the park's dramatic centerpiece.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3f/Tokyo_DisneySea_-_A_Walk_Along_Mount_Prometheus.jpg/1280px-Tokyo_DisneySea_-_A_Walk_Along_Mount_Prometheus.jpg"},{"name":"Cars Land","rarity":"rare","id":"cars-land","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Radiator Springs rebuilt at full scale in California Adventure, from Flo's V8 Café to the Cadillac Range peaks framing Ornament Valley.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Christmas_in_Cars_Land_%2828238055381%29.jpg/1280px-Christmas_in_Cars_Land_%2828238055381%29.jpg"},{"name":"World Showcase","rarity":"rare","id":"world-showcase","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Eleven national pavilions ring EPCOT's World Showcase Lagoon, each pairing architecture and food with performers from the country it honors.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/41/World_Showcase_Lagoon%2C_Epcot_%286068013401%29.jpg/1280px-World_Showcase_Lagoon%2C_Epcot_%286068013401%29.jpg"},{"name":"IllumiNations: Reflections of Earth","rarity":"rare","id":"illuminations-reflections-of-earth","subtitle":"Park Icons, Lands & Nighttime Shows","details":"EPCOT's lagoon finale from 1999 to 2019 centered on a rotating Earth globe covered in video screens, ringed by fireworks and flame torches.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1c/Reflections_of_Earth_9.jpg/1280px-Reflections_of_Earth_9.jpg"},{"name":"Super Nintendo World","rarity":"uncommon","id":"super-nintendo-world","subtitle":"Park Icons, Lands & Nighttime Shows","details":"A real-life Mushroom Kingdom of green pipes, spinning coins and Bowser's Castle, first opened at Universal Studios Japan in 2021.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8d/Kinopio%27s_cafe_exterior_at_Super_Nintendo_World_%28Universal_Studios_Japan%29.png/500px-Kinopio%27s_cafe_exterior_at_Super_Nintendo_World_%28Universal_Studios_Japan%29.png"},{"name":"New Orleans Square","rarity":"uncommon","id":"new-orleans-square","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Disneyland's 1966 waterfront district of iron balconies and courtyards was the last new land Walt Disney personally supervised.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c7/New_Orleans_Square_35_Night_2014.JPG/1280px-New_Orleans_Square_35_Night_2014.JPG"},{"name":"The Wizarding World of Harry Potter — Hogsmeade","rarity":"uncommon","id":"wizarding-world-hogsmeade","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Butterbeer carts and snow-capped roofs line this wizarding village at Islands of Adventure, with Honeydukes sweets and the Hogwarts Express at its station.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b6/Hogsmeade_%28Islands_of_Adventure%29_May_2023.JPG/1280px-Hogsmeade_%28Islands_of_Adventure%29_May_2023.JPG"},{"name":"Avengers Campus","rarity":"uncommon","id":"avengers-campus","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Marvel heroes recruit guests across this California Adventure campus, built around an Avengers headquarters and a web-slinger workshop.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/Disney_California_Adventure_%2851242016469%29.jpg/1280px-Disney_California_Adventure_%2851242016469%29.jpg"},{"name":"Tomorrowland","rarity":"uncommon","id":"tomorrowland","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Disneyland's vision of the future has been rebuilt repeatedly since 1955, trading atomic-age optimism for sleek retro-futurist spires.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Tomorrowland_%28Magic_Kingdom%29_entrance_2021.jpg/1280px-Tomorrowland_%28Magic_Kingdom%29_entrance_2021.jpg"},{"name":"Fantasyland","rarity":"uncommon","id":"fantasyland","subtitle":"Park Icons, Lands & Nighttime Shows","details":"The castle courtyard land where Disney's animated fairy tales become carousels, tea parties and flights over London in storybook style.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Fantasyland_Bavarian_architecture.jpg/1280px-Fantasyland_Bavarian_architecture.jpg"},{"name":"Adventureland","rarity":"uncommon","id":"adventureland","subtitle":"Park Icons, Lands & Nighttime Shows","details":"A jungle crossroads of tiki torches, riverboats and bazaars blending African, Asian and Polynesian styles since Disneyland opened in 1955.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a6/Adventureland_Disneyland.JPG/1280px-Adventureland_Disneyland.JPG"},{"name":"Frontierland","rarity":"uncommon","id":"frontierland","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Stockades, boardwalks and riverboat landings recreate America's pioneer frontier along the banks of the Rivers of America.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f6/Disneyland-BTR_entrance.jpg/1280px-Disneyland-BTR_entrance.jpg"},{"name":"Main Street Electrical Parade","rarity":"uncommon","id":"main-street-electrical-parade","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Thousands of synchronized lights turned floats and performers into glowing processions in this parade that first lit Disneyland in 1972.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Main_Street_Electrical_Parade_%E2%80%93_Casey_Junior.png/500px-Main_Street_Electrical_Parade_%E2%80%93_Casey_Junior.png"},{"name":"Rivers of Light","rarity":"uncommon","id":"rivers-of-light","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Animal Kingdom's nighttime lagoon show from 2017 to 2020 used floating lanterns, water screens and animal imagery, with no fireworks.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/Rivers_of_Light_-_Soft_Opening_-_February_12%2C_2017_%2832869396115%29.jpg/1280px-Rivers_of_Light_-_Soft_Opening_-_February_12%2C_2017_%2832869396115%29.jpg"},{"name":"Grauman's Chinese Theatre","rarity":"uncommon","id":"graumans-chinese-theatre","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Hollywood Studios' full-scale replica of the famous Hollywood landmark, complete with celebrity handprints set into its courtyard cement.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1f/Chinese_Theater_%2849560227308%29.jpg/960px-Chinese_Theater_%2849560227308%29.jpg"},{"name":"Sprookjesbos","rarity":"uncommon","id":"sprookjesbos","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Efteling's Fairy Tale Forest has brought European folktales to life with Anton Pieck's storybook scenes since the park opened in 1952.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/92/Efeteling_-_Sprookjesbos_-_The_Netherlands.jpg/1280px-Efeteling_-_Sprookjesbos_-_The_Netherlands.jpg"},{"name":"Seuss Landing","rarity":"uncommon","id":"seuss-landing","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Islands of Adventure's Seuss world bends every rail and roofline, honoring the whimsical, curve-filled look of Dr. Seuss's illustrations.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Seuss_Landing_03.jpg/1280px-Seuss_Landing_03.jpg"},{"name":"Wondrous Journeys","rarity":"uncommon","id":"wondrous-journeys","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Disneyland's fireworks show maps animated film moments across its castle and Main Street in a tribute to Disney animation history.","image":"https://www.disneytouristblog.com/wp-content/uploads/2021/07/wondrous-journeys-fireworks-disneyland-anaheim-california-1557.jpg"},{"name":"Liberty Square","rarity":"common","id":"liberty-square","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Magic Kingdom's colonial village honors the original 13 colonies with 13 lanterns hanging from its Liberty Tree.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/Disney_Liberty_Bell.jpg/1280px-Disney_Liberty_Bell.jpg"},{"name":"Mickey's Toontown","rarity":"common","id":"mickeys-toontown","subtitle":"Park Icons, Lands & Nighttime Shows","details":"A rubber-hose cartoon neighborhood of crooked houses and gag props, opened at Disneyland in 1993 after Roger Rabbit made Toontown famous.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/99/Toontown_%2828804712955%29.jpg/1280px-Toontown_%2828804712955%29.jpg"},{"name":"Critter Country","rarity":"common","id":"critter-country","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Disneyland's woodsy bayou land began life as Bear Country in 1972, built around caves, log cabins and a riverside hungry-bear restaurant.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/ba/Hungry_Bear_Restaurant%2C_Critter_Country%2C_Disneyland%2C_Anaheim%2C_California.jpg/1280px-Hungry_Bear_Restaurant%2C_Critter_Country%2C_Disneyland%2C_Anaheim%2C_California.jpg"},{"name":"Buena Vista Street","rarity":"common","id":"buena-vista-street","subtitle":"Park Icons, Lands & Nighttime Shows","details":"California Adventure's entrance recreates the Los Angeles Walt Disney arrived in during 1923, with trolley bells and palm trees.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/Buena_Vista_Street_at_California_Adventure.jpg/1280px-Buena_Vista_Street_at_California_Adventure.jpg"},{"name":"The Earffel Tower","rarity":"common","id":"the-earffel-tower","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Hollywood Studios' original icon from 1989 to 2016 was a studio water tower topped with a giant pair of Mickey Mouse ears.","image":"https://upload.wikimedia.org/wikipedia/commons/7/70/DisneyMgmEarfulTower.jpg"},{"name":"Sorcerer's Hat","rarity":"common","id":"sorcerers-hat","subtitle":"Park Icons, Lands & Nighttime Shows","details":"A 122-foot blue sorcerer's hat served as Hollywood Studios' icon from 2001 to 2015, modeled on Mickey's hat from Fantasia.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/44/Sorcerer%27s_Hat_2008.jpg/1280px-Sorcerer%27s_Hat_2008.jpg"},{"name":"Electrical Water Pageant","rarity":"common","id":"electrical-water-pageant","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Glowing sea creatures have floated across Walt Disney World's Seven Seas Lagoon in this electric barge parade since opening year, 1971.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/Electrical_Water_Pageant.jpg/1280px-Electrical_Water_Pageant.jpg"},{"name":"Paint the Night","rarity":"common","id":"paint-the-night","subtitle":"Park Icons, Lands & Nighttime Shows","details":"More than a million LED lights paint this after-dark parade, first staged for Disneyland's 60th anniversary celebration in 2015.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d1/Paint_the_Night_%2829354164162%29.jpg/1280px-Paint_the_Night_%2829354164162%29.jpg"},{"name":"Remember... Dreams Come True","rarity":"common","id":"remember-dreams-come-true","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Disneyland's 50th-anniversary fireworks in 2005 stitched together moments and music from the park's classic attractions in tribute.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/ca/Disneyland_Fireworks_%287488813778%29.jpg/1280px-Disneyland_Fireworks_%287488813778%29.jpg"},{"name":"Epcot Forever","rarity":"common","id":"epcot-forever","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Created as EPCOT's interim lagoon show in 2019, this fireworks revue celebrated park history with giant kites towed by jet skis.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3e/Watching_Fireworks_at_EPCOT_%2849576259696%29.jpg/1280px-Watching_Fireworks_at_EPCOT_%2849576259696%29.jpg"},{"name":"Disney Dreams!","rarity":"common","id":"disney-dreams","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Disneyland Paris's nighttime spectacular projects Peter Pan's shadow across its castle amid fountains and fireworks; it debuted in 2012.","image":"https://radiodisneyclub.fr/wp-content/uploads/2017/01/fdp11810.jpg"},{"name":"Ignite the Dream","rarity":"common","id":"ignite-the-dream","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Shanghai Disneyland's castle show pairs fireworks and fountains with scenes from Disney films and debuted with the resort in 2016.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Disneyland_%28201325775%29.jpeg/960px-Disneyland_%28201325775%29.jpeg"},{"name":"Fantillusion","rarity":"common","id":"fantillusion","subtitle":"Park Icons, Lands & Nighttime Shows","details":"This light parade of fairies and villains began in Tokyo in 1995 before moving to Disneyland Paris, where it glowed from 2003 to 2012.","image":"https://disneyland-paris-photos.s3.amazonaws.com/images/disney-fantillusion-parade-1.width-900.format-webp.webp"},{"name":"Toon Lagoon","rarity":"common","id":"toon-lagoon","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Islands of Adventure's comic-strip water land soaks guests under Popeye barges and Dudley Do-Right flumes drawn in Sunday-funnies style.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a9/Islands_of_Adventure_-_Toon_Lagoon_%2815801661201%29.jpg/1280px-Islands_of_Adventure_-_Toon_Lagoon_%2815801661201%29.jpg"},{"name":"Port of Entry","rarity":"common","id":"port-of-entry","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Islands of Adventure's entry village of bazaars and towers is crowned by the Pharos Lighthouse, the park's guiding beacon since 1999.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/72/Port_of_Entry_1.jpg/1280px-Port_of_Entry_1.jpg"},{"name":"The Lost Continent","rarity":"common","id":"the-lost-continent","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Once Islands of Adventure's land of myths and Sinbad stunts, most of this area was absorbed into the Wizarding World after 2010.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/The_Lost_Continent_11.jpg/960px-The_Lost_Continent_11.jpg"},{"name":"Jurassic Park (Islands of Adventure)","rarity":"common","id":"jurassic-park-islands-of-adventure","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Towering entrance gates and a discovery center bring Isla Nublar to Islands of Adventure, dinosaurs included since the park opened in 1999.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fa/Jurassic_Park_Entrance_Arch_at_the_Universal_Islands_of_Adventure.JPG/1280px-Jurassic_Park_Entrance_Arch_at_the_Universal_Islands_of_Adventure.JPG"},{"name":"Camp Snoopy","rarity":"common","id":"camp-snoopy","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Knott's Berry Farm's Peanuts wilderness camp, added in 1983, packs pint-size logs, canoes and beagle humor into a High Sierra setting.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7d/Camp_Snoopy_%28Knott%27s_Berry_Farm%29_2025_1.jpg/1280px-Camp_Snoopy_%28Knott%27s_Berry_Farm%29_2025_1.jpg"},{"name":"Sesame Street Land","rarity":"common","id":"sesame-street-land","subtitle":"Park Icons, Lands & Nighttime Shows","details":"SeaWorld Orlando's walkable Sesame Street, opened in 2019, recreates the TV neighborhood including Hooper's Store and the famous 123 stoop.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/Sunny_Day_Carousel_Mar_2026.jpg/1280px-Sunny_Day_Carousel_Mar_2026.jpg"},{"name":"Miniland (Legoland)","rarity":"common","id":"miniland-legoland","subtitle":"Park Icons, Lands & Nighttime Shows","details":"Legoland's miniature cities pack famous landmarks built from millions of LEGO bricks into walk-through scenes at parks worldwide.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d1/Miniland_-_Venise_%28Legoland%29.jpg/1280px-Miniland_-_Venise_%28Legoland%29.jpg"},{"name":"Siam Park","rarity":"epic","id":"siam-park","subtitle":"Water Parks & Slides","details":"Opened in 2008 in Adeje, Tenerife, this Thai-themed water kingdom built into a hillside is anchored by a giant wave palace and the near-vertical Tower of Power.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a1/Siamparkentrada1.JPG/1280px-Siamparkentrada1.JPG"},{"name":"Yas Waterworld","rarity":"epic","id":"yas-waterworld","subtitle":"Water Parks & Slides","details":"Abu Dhabi mega-park opened in 2013 with an Emirati pearl-diving theme, more than 40 rides and slides, and the Liwa Loop freefall looping slide.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/Yas_Waterworld_Abu_Dhabi_3.jpg/1280px-Yas_Waterworld_Abu_Dhabi_3.jpg"},{"name":"Aquaventure Waterpark (Dubai)","rarity":"epic","id":"aquaventure-waterpark-dubai","subtitle":"Water Parks & Slides","details":"Atlantis The Palm's Dubai water park pairs tower slides and a shark safari with signature river rapids, lagoons and a long private beach.","image":"https://mybayutcdn.bayut.com/mybayut/wp-content/uploads/water-parks-in-dubai-ar09112020-1024x640.jpg"},{"name":"Typhoon Lagoon","rarity":"rare","id":"typhoon-lagoon","subtitle":"Water Parks & Slides","details":"Disney water park in Orlando themed as a storm-ravaged tropical lagoon, centred on Miss Tilly, a shrimp boat impaled atop Mount Mayday.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d8/Disney%27s_Typhoon_Lagoon_%2828923104866%29.jpg/1280px-Disney%27s_Typhoon_Lagoon_%2828923104866%29.jpg"},{"name":"Blizzard Beach","rarity":"rare","id":"blizzard-beach","subtitle":"Water Parks & Slides","details":"Disney's Orlando water park imagines a freak snowstorm turned ski resort, with chairlifts serving melting slopes and the 120-foot Summit Plummet.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Blizzard_Beach_Disney_Water_Park_-_panoramio.jpg/1280px-Blizzard_Beach_Disney_Water_Park_-_panoramio.jpg"},{"name":"Universal Volcano Bay","rarity":"rare","id":"universal-volcano-bay","subtitle":"Water Parks & Slides","details":"Universal Orlando's tropical water theme park, opened in 2017 around the 200-foot Krakatau volcano, with wearable ride reservations instead of queues.","image":"https://upload.wikimedia.org/wikipedia/commons/6/69/Krakatau_at_Volcano_Bay.jpg"},{"name":"Schlitterbahn New Braunfels","rarity":"rare","id":"schlitterbahn-new-braunfels","subtitle":"Water Parks & Slides","details":"The original Schlitterbahn, opened in 1979 on the spring-fed Comal River in Texas, mixing natural river rides with uphill water coasters.","image":"https://upload.wikimedia.org/wikipedia/commons/9/96/Schlitterbahn_New_Braunfels_Chute_2004.jpg"},{"name":"Noah's Ark Water Park","rarity":"rare","id":"noahs-ark-water-park","subtitle":"Water Parks & Slides","details":"Seventy-acre water park in Wisconsin Dells, packed with dozens of slides, wave pools and the looping Scorpion's Tail waterslide.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/85/Noah%27s_Ark_Water_Park.jpg/1280px-Noah%27s_Ark_Water_Park.jpg"},{"name":"Summit Plummet","rarity":"uncommon","id":"summit-plummet","subtitle":"Water Parks & Slides","details":"At Disney's Blizzard Beach, a 120-foot freefall body slide styled as a ski jump, sending riders down a near-vertical drop at highway speeds.","image":"https://cdn1.parksmedia.wdprapps.disney.com/resize/mwImage/1/800/450/75/dam/wdpro-assets/gallery/attractions/blizzard-beach/summit-plummet/summit-plummet-gallery05.jpg?1699632146424"},{"name":"Leap of Faith","rarity":"uncommon","id":"leap-of-faith","subtitle":"Water Parks & Slides","details":"At Aquaventure on Paradise Island, Bahamas, a 60-foot near-vertical slide that plunges through a clear tunnel inside a shark-filled lagoon.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fe/Mayan_Leap_of_Faith_%26_Shark_Tank_Atlantis_Paradise_Island_Photo_Don_Ramey_Logan.jpg/1280px-Mayan_Leap_of_Faith_%26_Shark_Tank_Atlantis_Paradise_Island_Photo_Don_Ramey_Logan.jpg"},{"name":"Insano","rarity":"uncommon","id":"insano","subtitle":"Water Parks & Slides","details":"At Beach Park in Brazil, a 41-metre body slide opened in 1989; riders freefall for about five seconds and hit speeds near 65 mph on the way down.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/40/Insano_-_Beach_Park.jpg/960px-Insano_-_Beach_Park.jpg"},{"name":"Master Blaster","rarity":"uncommon","id":"master-blaster","subtitle":"Water Parks & Slides","details":"Schlitterbahn New Braunfels' uphill water coaster, opened in 1996, blasting two-person rafts uphill on powerful water jets between downhill drops.","image":"https://www.tourtexas.com/content_images/Master%20Blaster%201.jpg"},{"name":"Wildebeest","rarity":"uncommon","id":"wildebeest","subtitle":"Water Parks & Slides","details":"Holiday World's hydro-magnetic water coaster, opened in 2010 at over 1,700 feet long; linear induction motors launch rafts uphill again and again.","image":"https://upload.wikimedia.org/wikipedia/commons/2/29/WildebeestRide_Overview.jpg"},{"name":"Mammoth","rarity":"uncommon","id":"mammoth","subtitle":"Water Parks & Slides","details":"Holiday World's six-passenger water coaster, opened in 2012 at 1,763 feet long, spinning round rafts through dark tunnels and open-air hills.","image":"https://holidayworld.com/wp-content/uploads/2023/10/Mammoth-45degree-Drop.webp"},{"name":"Ko'okiri Body Plunge","rarity":"uncommon","id":"kookiri-body-plunge","subtitle":"Water Parks & Slides","details":"Volcano Bay's trapdoor body slide drops riders 125 feet at a 70-degree angle, straight through the heart of the Krakatau volcano.","image":"https://orlandoinformer.com/wp-content/uploads/2020/01/20170525-_DSC6968.jpg"},{"name":"Krakatau Aqua Coaster","rarity":"uncommon","id":"krakatau-aqua-coaster","subtitle":"Water Parks & Slides","details":"Volcano Bay's four-person canoe coaster winds in and out of the Krakatau volcano, using magnets to pull rafts uphill through mist and twists.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/47/Krakatau_Aqua_Coaster_%2837170103801%29.jpg/1280px-Krakatau_Aqua_Coaster_%2837170103801%29.jpg"},{"name":"Tower of Power","rarity":"uncommon","id":"tower-of-power","subtitle":"Water Parks & Slides","details":"Siam Park's signature 28-metre slide, dropping riders at speed through a clear tube that runs through an aquarium of sharks and rays.","image":"https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjXLB3_2Vjn3xGNfUritBKaQeOSCdaLIpNeYCl8MtI72DEGl4WGvElt8bTxyNDOb2VTi95t4TfCLXC1tpMU0mqiGKqTNxfkX1A4UUijUFRTRWyJn5sM2aCwy7YV0L970D4rcSMgM5YYyjY/s640/Siam+Park.png"},{"name":"Ihu's Breakaway Falls","rarity":"uncommon","id":"ihus-breakaway-falls","subtitle":"Water Parks & Slides","details":"Aquatica Orlando's drop-pod slide, opened in 2014, where the floor vanishes beneath riders in three separate trapdoor capsules 80 feet up.","image":"https://attractionsmagazine.com/wp-content/uploads/2015/05/Ihus-breakaway-falls-at-aquatica.jpg"},{"name":"Water Country USA","rarity":"common","id":"water-country-usa","subtitle":"Water Parks & Slides","details":"Surf-themed water park near Williamsburg, Virginia, pairing a wave pool and lazy river with the freefall Vanish Point drop slides.","image":"https://cdn.tripster.com/media/product/gallery/original/Water_Country_USA_(53192).jpg"},{"name":"Splish Splash","rarity":"common","id":"splish-splash","subtitle":"Water Parks & Slides","details":"Long Island water park in Calverton, New York, opened in 1991, known for the Alien Invasion funnel slide and shaded picnic groves.","image":"https://assets.simpleviewinc.com/simpleview/image/upload/c_limit,h_1200,q_75,w_1200/v1/crm/newyorkstate/Splish-Splash-Shoot-053121-General-Park-Asset-1-16x9_DC57056F-DF0E-47CE-86D1D57229E339AC_876ee658-9e1b-8847-c61933e9bcd4cfc8.jpg"},{"name":"Adventure Island (Tampa)","rarity":"common","id":"adventure-island-tampa","subtitle":"Water Parks & Slides","details":"Busch Gardens' Key West-themed water park in Tampa, Florida, with mangrove lagoons, waterfalls and the Solar Vortex raft slide.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3a/Adventure_Island_%287250781166%29.jpg/1280px-Adventure_Island_%287250781166%29.jpg"},{"name":"Aquatica Orlando","rarity":"common","id":"aquatica-orlando","subtitle":"Water Parks & Slides","details":"SeaWorld's Orlando water park, mixing animal encounters with slides; its Dolphin Plunge tubes pass through a Commerson's dolphin habitat.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4a/Aquatica-roasrapids.jpg"},{"name":"Aquatica San Antonio","rarity":"common","id":"aquatica-san-antonio","subtitle":"Water Parks & Slides","details":"SeaWorld San Antonio's water park, where the Stingray Falls slide finishes with a grotto glide past cownose rays and tropical fish.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/Aquatica_San_Antonio_overview_2.jpg/1280px-Aquatica_San_Antonio_overview_2.jpg"},{"name":"Six Flags White Water (Atlanta)","rarity":"common","id":"six-flags-white-water-atlanta","subtitle":"Water Parks & Slides","details":"Marietta, Georgia water park opened in 1984, shaded by tall pines and anchored by the Dive Bomber trapdoor slide and a giant wave pool.","image":"https://cdn.sanity.io/images/bsnrdz4t/production/3ffa17176f35b8b09f19a3acb6b752f8f38e89ab-7008x4672.jpg?w=1024&q=80&fit=clip&auto=format"},{"name":"Six Flags Hurricane Harbor (New Jersey)","rarity":"common","id":"six-flags-hurricane-harbor-new-jersey","subtitle":"Water Parks & Slides","details":"Six Flags Great Adventure's water park in Jackson, New Jersey, with a giant wave pool and the King Cobra slide shaped like a striking snake.","image":"https://i2.wp.com/www.tripsavvy.com/thmb/uBzNjsxfwN85XYvUpzj2C71N0Kk=/950x0/filters:no_upscale():max_bytes(150000):strip_icc()/SixFlagsHurricaneHarborwaterparkNewJersey-5c424fce46e0fb0001c4cd75.jpg"},{"name":"Cowabunga Bay (Las Vegas)","rarity":"common","id":"cowabunga-bay-las-vegas","subtitle":"Water Parks & Slides","details":"Retro surf-themed water park in Henderson, near Las Vegas, built around a big wave pool, a lazy river and bright mat racers and tube slides.","image":"https://prodlisting.livabl.com/imageSponsors/xlarge/2024_03_09_08_43_09_2024_03_09_03_42_57_360_nev_lasvegas_pic_cowabungabay_photoshoot_4of4.webp"},{"name":"Wet'n'Wild Gold Coast","rarity":"common","id":"wet-n-wild-gold-coast","subtitle":"Water Parks & Slides","details":"Australia's Gold Coast water park, opened in 1984, famous for its AquaLoop trapdoor slides and the giant funnel of the Tornado.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6b/Wetnwildaqualoopcarpark.JPG/1280px-Wetnwildaqualoopcarpark.JPG"},{"name":"Raging Waters (San Dimas)","rarity":"common","id":"raging-waters-san-dimas","subtitle":"Water Parks & Slides","details":"California water park in San Dimas, opened in 1983, with high-speed mat slides, a big wave pool and a lazy river through tropical landscaping.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/98/Little_Dipper_Lagoon.jpg/1280px-Little_Dipper_Lagoon.jpg"},{"name":"Zoombezi Bay","rarity":"common","id":"zoombezi-bay","subtitle":"Water Parks & Slides","details":"Water park beside the Columbus Zoo in Powell, Ohio, where slides include the dark family raft ride Tahitian Twister and a wave pool beach.","image":"https://midwestexplored.com/wp-content/uploads/2021/11/Zoombezi-Bay-Waterparks-in-Ohio.jpg"},{"name":"Soak City (Kings Island)","rarity":"common","id":"soak-city-kings-island","subtitle":"Water Parks & Slides","details":"Kings Island's included water park in Mason, Ohio, with tropical lagoons, mat racers and the Tropical Plunge drop-pod complex.","image":"https://upload.wikimedia.org/wikipedia/commons/f/fa/Soak_City_Tazmanian_Typhoon.jpg"},{"name":"Carolina Harbor","rarity":"common","id":"carolina-harbor","subtitle":"Water Parks & Slides","details":"Carowinds' included water park on the North-South Carolina line, harbour-themed, with the Blackbeard's Revenge slide complex and surf pool.","image":"https://attractionsmagazine.com/wp-content/uploads/2016/06/CarolinaHarbor-752x500.jpg"},{"name":"Great Wolf Lodge (Mason, Ohio)","rarity":"common","id":"great-wolf-lodge-mason-ohio","subtitle":"Water Parks & Slides","details":"Indoor water park resort in Mason, Ohio, kept at a balmy 84 degrees year-round, with family slides, a wave pool and a tipping-bucket fort.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Great_Wolf_Lodge_indoor_water_park_Cincinnati.jpg/1280px-Great_Wolf_Lodge_indoor_water_park_Cincinnati.jpg"},{"name":"Schlitterbahn Galveston","rarity":"common","id":"schlitterbahn-galveston","subtitle":"Water Parks & Slides","details":"Island Schlitterbahn in Galveston, Texas, opened in 2006, with a convertible indoor section for winter and the uphill MASSIV water coaster.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5c/Schlitterbahn_Waterpark_Galveston_Texas_2026.jpg/1280px-Schlitterbahn_Waterpark_Galveston_Texas_2026.jpg"},{"name":"Slush Gusher","rarity":"common","id":"slush-gusher","subtitle":"Water Parks & Slides","details":"Blizzard Beach's gentler sister to Summit Plummet, a 90-foot body slide with two rolling humps that briefly lift riders out of the chute.","image":"https://waterparkhotelsorlando.com/wp-content/uploads/slush-gusher-water-slide-from-bottom-blizzard-beach-960.jpg"},{"name":"Teamboat Springs","rarity":"common","id":"teamboat-springs","subtitle":"Water Parks & Slides","details":"Blizzard Beach family raft ride, about 1,200 feet of whitewater rapids and waterfalls carrying six riders at a time down Mount Gushmore.","image":"https://www.attractiontickets.com/sites/default/files/2019-06/teamboat_springs.jpg"},{"name":"Miss Adventure Falls","rarity":"common","id":"miss-adventure-falls","subtitle":"Water Parks & Slides","details":"Typhoon Lagoon family raft ride, opened in 2017, floating four riders past a wrecked treasure ship and an animatronic parrot.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6b/Miss_Adventure_Falls_%2833492060033%29.jpg/960px-Miss_Adventure_Falls_%2833492060033%29.jpg"},{"name":"Dolphin Plunge","rarity":"common","id":"dolphin-plunge","subtitle":"Water Parks & Slides","details":"Aquatica Orlando's clear-tube body slides run straight through a habitat of black-and-white Commerson's dolphins, the park's signature sight.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b8/Dolphinplunge-adjusted.jpg/1280px-Dolphinplunge-adjusted.jpg"},{"name":"Cheetah Chase","rarity":"common","id":"cheetah-chase","subtitle":"Water Parks & Slides","details":"Holiday World's launched water coaster, opened in 2020, racing two family rafts side by side uphill on water jets through tunnels and turns.","image":"https://holidayworld.com/wp-content/uploads/2023/11/Cheetah-Chase-from-Northwest.webp"},{"name":"Singha","rarity":"common","id":"singha","subtitle":"Water Parks & Slides","details":"Siam Park's water coaster, opened in 2015, blasting four-person rafts through high-banked turns and dark sections high above the park.","image":"https://www.tenerifeaz.es/storage/01hkpmg24s14mgm25jwt18g004/149/tenerifeaz-siam-park-singha-e1676646024371.jpg"},{"name":"Kinnaree","rarity":"common","id":"kinnaree","subtitle":"Water Parks & Slides","details":"Siam Park mega-slide, opened in 2012, combining steep drops with a giant funnel wall that swings four-person rafts from side to side.","image":"https://www.tiqets.com/blog/wp-content/uploads/2024/01/ILOVETHEWORLD_6_kinnaree_02_m-1.jpg"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
